-- 2026-11-09 spec mapping: question_templates -> DfE / AQA 8300 / Edexcel 1MA1 / OCR J560 (Foundation)
create table if not exists public.template_spec_refs (
  template_id text references public.question_templates(id),
  board text check (board in ('DfE','AQA','Edexcel','OCR')),
  spec_ref text,
  spec_text text,
  tier text default 'Foundation',
  verified boolean default false,
  source_url text,
  notes text,
  primary key (template_id, board, spec_ref)
);
alter table public.template_spec_refs enable row level security;
create policy "read spec refs" on public.template_spec_refs for select to authenticated using (true);

with txt(ref, t) as (values
('N2', 'apply the four operations, including formal written methods, to integers, decimals and simple fractions (proper and improper), and mixed numbers – all both positive and negative'),
('N3', 'recognise and use relationships between operations, including inverse operations (e.g. cancellation to simplify calculations and expressions); use conventional notation for priority of operations, including brackets, powers, roots and reciprocals'),
('N4', 'use the concepts and vocabulary of prime numbers, factors (divisors), multiples, common factors…'),
('N8', 'calculate exactly with fractions…'),
('N10', 'work interchangeably with terminating decimals and their corresponding fractions (such as 3.5 and 7/2 or 0.375 or 3/8)'),
('N11', 'identify and work with fractions in ratio problems'),
('N12', 'interpret fractions and percentages as operators'),
('N13', 'use standard units of mass, length, time, money and other measures (including standard compound measures) using…'),
('N15', 'round numbers and measures to an appropriate degree of accuracy (e.g. to a specified number of decimal places…'),
('A2', 'substitute numerical values into formulae and expressions, including scientific formulae'),
('A17', 'solve linear equations in one unknown algebraically (including those with the unknown on both sides of the equation)…'),
('A25', 'deduce expressions to calculate the nth term of linear sequences'),
('R1', 'change freely between related standard units (e.g. time, length, area, volume/capacity, mass) and compound units…'),
('R4', 'use ratio notation, including reduction to simplest form'),
('R5', 'divide a given quantity into two parts in a given part:part or part:whole ratio; express the division of a quantity into two parts as a ratio; apply ratio to real contexts and problems (such as those involving conversion, comparison, scaling, mixing, concentrations)'),
('R8', 'relate ratios to fractions and to linear functions'),
('R9', 'define percentage as ''number of parts per hundred''; interpret percentages and percentage changes as a fraction or a decimal…; express one quantity as a percentage of another; … solve problems involving percentage change, including percentage increase/decrease and original value problems…'),
