aqa_url(l, url) as (values ('N', 'https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/subject-content/3.1-number'), ('A', 'https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/specification/subject-content/3.2-algebra'), ('R', 'https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/specification/subject-content/3.3-ratio-proportion-and-rates-of-change'), ('G', 'https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/specification/subject-content/3.4-geometry-and-measures'), ('P', 'https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/specification/subject-content/3.5-probability'), ('S', 'https://www.aqa.org.uk/subjects/mathematics/gcse/mathematics-8300/specification/subject-content/3.6-statistics')),
edx_head(l, h) as (values ('N','1 Number'),('A','2 Algebra'),('R','3 Ratio, proportion and rates of change'),('G','4 Geometry and measures'),('P','5 Probability'),('S','6 Statistics')),
r as (
  select m.template_id, 'DfE' as board, c as spec_ref, false as verified, 'https://www.gov.uk/government/publications/gcse-mathematics-subject-content-and-assessment-objectives' as url,
         'DfE PDF not opened (link blocked); wording as reproduced in AQA/Edexcel specs.' || coalesce(' ' || m.note, '') as notes
  from m, unnest(m.dfe) c
  union all
  select m.template_id, 'AQA', c, true, (select url from aqa_url where l = left(c,1)),
         'Column: ' || case when c in ('G20','P5') then 'additional foundation' else 'basic foundation' end || '.'
         || case when c = 'R5' and m.template_id = 'DEC-03' then ' AQA note: "including better value or best-buy problems."' else '' end
  from m, unnest(m.dfe || m.aqa_extra) c
  union all
  select m.template_id, 'Edexcel', c, true, 'https://qualifications.pearson.com/content/dam/pdf/GCSE/mathematics/2015/specification-and-sample-assesment/gcse-maths-2015-specification.pdf',
         'In Foundation tier section, ' || (select h from edx_head where l = left(c,1)) || ' (Issue 2).'
  from m, unnest(m.dfe) c
  union all
  select m.template_id, 'OCR', c, true, 'https://mmerevise.co.uk/wp-content/uploads/2017/09/168982-specification-gcse-mathematics-j560.pdf',
         'Read from mirror of OCR doc 168982 (ocr.org.uk PDF blocked). Tier column not readable; Foundation inferred from DfE tiering.'
         || case when m.template_id = 'RAT-03' then ' ' || m.note else '' end
  from m, unnest(m.ocr) c
)
insert into public.template_spec_refs (template_id, board, spec_ref, spec_text, tier, verified, source_url, notes)
select r.template_id, r.board, r.spec_ref, txt.t, 'Foundation', r.verified, r.url, r.notes
from r join txt on txt.ref = r.spec_ref
on conflict (template_id, board, spec_ref) do update set spec_text = excluded.spec_text, tier = excluded.tier,
  verified = excluded.verified, source_url = excluded.source_url, notes = excluded.notes;
